sparql_tries.sparql:
SELECT DISTINCT ?year WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber "26V430000" ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model ;
           rc:modelYear ?year .
  ?model rc:name "TELLURIDE" ;
         rc:ofMake ?make .
  ?make rc:name "KIA" .
}
ORDER BY ?year

SELECT DISTINCT ?campaignNumber ?make ?date WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber ?campaignNumber ;
            rc:doNotDrive true ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:ofMake ?mk .
  ?mk rc:name ?make .
  FILTER(?make IN ("HYUNDAI", "KIA", "GENESIS"))
  OPTIONAL { ?campaign rc:reportReceivedDate ?date }
}
ORDER BY DESC(?date) ?campaignNumber

SELECT DISTINCT ?campaignNumber ?initiatedBy ?reportReceivedDate ?manufacturerName
WHERE {
  ?recall a rc:RecallCampaign ;
          rc:campaignNumber ?campaignNumber ;
          rc:initiatedBy ?initiatedBy .
  OPTIONAL { ?recall rc:reportReceivedDate ?reportReceivedDate . }
  OPTIONAL { ?recall rc:filedBy ?mfr . ?mfr rc:name ?manufacturerName . }
  FILTER(REGEX(STR(?initiatedBy), "OVSC|Office of Vehicle Safety Compliance", "i"))
}
ORDER BY DESC(?reportReceivedDate) ?campaignNumber

SELECT DISTINCT ?campaignNumber ?date WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber ?campaignNumber ;
            rc:reportReceivedDate ?date ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:name "PALISADE" ;
         rc:ofMake ?make .
  ?make rc:name "HYUNDAI" .
  FILTER(YEAR(?date) = 2024)
}
ORDER BY ?date

SELECT ?componentName (COUNT(DISTINCT ?campaign) AS ?campaignCount)
WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:affectsComponent ?component ;
            rc:affects ?variant .
  ?variant rc:ofModel/rc:ofMake ?make .
  ?make rc:name ?makeName .
  FILTER(?makeName IN ("HYUNDAI", "KIA"))
  ?component rc:name ?componentName .
  FILTER EXISTS { ?component skos:broader ?parent }
  FILTER EXISTS {
    ?c1 rc:affectsComponent ?component ; rc:affects ?v1 .
    ?v1 rc:ofModel/rc:ofMake/rc:name "HYUNDAI" .
  }
  FILTER EXISTS {
    ?c2 rc:affectsComponent ?component ; rc:affects ?v2 .
    ?v2 rc:ofModel/rc:ofMake/rc:name "KIA" .
  }
}
GROUP BY ?componentName
ORDER BY DESC(?campaignCount) ?componentName
LIMIT 1

SELECT ?campaignNumber (COUNT(DISTINCT ?make) AS ?makeCount) (GROUP_CONCAT(DISTINCT ?makeName; separator=", ") AS ?makes) WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber ?campaignNumber ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:ofMake ?make .
  ?make rc:name ?makeName .
}
GROUP BY ?campaignNumber
HAVING (COUNT(DISTINCT ?make) > 1)
ORDER BY DESC(?makeCount) ?campaignNumber

SELECT DISTINCT ?campaignNumber ?reportReceivedDate WHERE {
  ?make a rc:Make ; rc:name "HYUNDAI" .
  ?model a rc:VehicleModel ; rc:ofMake ?make ; rc:name "SANTA FE" .
  ?variant a rc:VehicleVariant ; rc:ofModel ?model ; rc:modelYear "2021"^^xsd:gYear .
  ?campaign a rc:RecallCampaign ; rc:affects ?variant ; rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?campaign rc:reportReceivedDate ?reportReceivedDate . }
}
ORDER BY ?reportReceivedDate ?campaignNumber

SELECT (COUNT(DISTINCT ?campaign) AS ?count) WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:reportReceivedDate ?date ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:ofMake ?make .
  ?make rc:name ?makeName .
  FILTER(?makeName IN ("HYUNDAI", "KIA", "GENESIS"))
  FILTER(YEAR(?date) = 2023)
}

SELECT ?topName (COUNT(DISTINCT ?model) AS ?modelCount) WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:affectsComponent ?comp ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?comp skos:broader* ?top .
  ?top a rc:Component .
  FILTER NOT EXISTS { ?top skos:broader ?parent . }
  ?top rc:name ?topName .
}
GROUP BY ?topName
ORDER BY DESC(?modelCount)
LIMIT 1

SELECT ?topName (COUNT(DISTINCT ?c) AS ?campaigns) WHERE {
  ?c a rc:RecallCampaign ;
     rc:affects ?v ;
     rc:affectsComponent ?comp .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name "GENESIS" .
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?parent }
  ?top rc:name ?topName .
}
GROUP BY ?topName
ORDER BY DESC(?campaigns)
LIMIT 1

SELECT ?year (COUNT(DISTINCT ?c) AS ?cnt) WHERE {
  ?c a rc:RecallCampaign ;
     rc:reportReceivedDate ?d ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?mkName .
  FILTER(?mkName IN ("HYUNDAI", "KIA", "GENESIS"))
  BIND(YEAR(?d) AS ?year)
}
GROUP BY ?year
ORDER BY DESC(?cnt) ASC(?year)
LIMIT 1

SELECT DISTINCT ?campaignNumber ?manufacturer ?reportDate ?componentName WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?r rc:filedBy ?m . ?m rc:name ?manufacturer . }
  OPTIONAL { ?r rc:reportReceivedDate ?reportDate . }
  OPTIONAL { ?r rc:affectsComponent ?c . ?c rc:name ?componentName . }
  OPTIONAL { ?r rc:defectSummary ?defect . }
  OPTIONAL { ?r rc:consequenceSummary ?consequence . }
  FILTER (
    ( BOUND(?componentName) && REGEX(?componentName, "HYDROGEN", "i") && REGEX(?componentName, "LEAK|DETECT", "i") )
    ||
    ( BOUND(?defect) && REGEX(?defect, "hydrogen", "i") && REGEX(?defect, "leak", "i") )
    ||
    ( BOUND(?consequence) && REGEX(?consequence, "hydrogen", "i") && REGEX(?consequence, "leak", "i") )
  )
}
ORDER BY ?reportDate ?campaignNumber

SELECT DISTINCT ?campaignNumber ?manufacturerName ?reportReceivedDate WHERE {
  ?recall a rc:RecallCampaign ;
          rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?recall rc:filedBy ?mfr . ?mfr rc:name ?manufacturerName . }
  OPTIONAL { ?recall rc:reportReceivedDate ?reportReceivedDate . }
  {
    ?recall rc:defectSummary ?text .
  } UNION {
    ?recall rc:consequenceSummary ?text .
  } UNION {
    ?recall rc:correctiveSummary ?text .
  } UNION {
    ?recall rc:rootCause ?text .
  } UNION {
    ?recall rc:affectsComponent ?comp . ?comp rc:name ?text .
  }
  FILTER(REGEX(?text, "integrated charging control unit|\\bICCU\\b", "i"))
}
ORDER BY DESC(?reportReceivedDate) ?campaignNumber

SELECT DISTINCT ?campaignNumber ?manufacturerName ?reportReceivedDate ?defectSummary
WHERE {
  ?recall a rc:RecallCampaign ;
          rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?recall rc:defectSummary ?defectSummary . }
  OPTIONAL { ?recall rc:rootCause ?rootCause . }
  OPTIONAL { ?recall rc:reportReceivedDate ?reportReceivedDate . }
  OPTIONAL { ?recall rc:filedBy ?mfr . ?mfr rc:name ?manufacturerName . }
  BIND(LCASE(CONCAT(COALESCE(STR(?defectSummary), ""), " ", COALESCE(STR(?rootCause), ""))) AS ?text)
  FILTER(
    (CONTAINS(?text, "water") || CONTAINS(?text, "moisture") || CONTAINS(?text, "liquid") || CONTAINS(?text, "corrosion"))
    && (CONTAINS(?text, "trailer") || CONTAINS(?text, "tow") || CONTAINS(?text, "hitch"))
    && (CONTAINS(?text, "module") || CONTAINS(?text, "control unit") || CONTAINS(?text, "connector") || CONTAINS(?text, "harness") || CONTAINS(?text, "wiring"))
  )
}
ORDER BY DESC(?reportReceivedDate) ?campaignNumber

SELECT DISTINCT ?campaignNumber ?defect WHERE {
  ?recall a rc:RecallCampaign ;
          rc:campaignNumber ?campaignNumber ;
          rc:defectSummary ?defect .
  FILTER(REGEX(?defect, "connecting rod bearing", "i") && REGEX(?defect, "wear", "i"))
}
ORDER BY ?campaignNumber
